//! Single-byte code pages beyond Windows-1252 (the Text Import Wizard's File
//! origin, and the Macintosh and MS-DOS Save As text types; #761).
//!
//! Every page here is ASCII below 0x80. Its high half comes from
//! [`tables`], generated by `tools/gen_codepages.py` from Windows' own
//! decoding (what Excel on Windows reads a file with): a byte reads as
//! Windows reads it, which for some unassigned bytes is the C1 control of
//! the same number, except that a byte Windows rejects or reads as a
//! private-use character reads as U+FFFD. A character the page has no byte
//! for is written as `?`, never a look-alike.

mod tables;

/// The code pages [`decode`] and [`encode`] know, by number.
pub fn pages() -> impl Iterator<Item = u16> {
    tables::PAGES.iter().map(|(page, _)| *page)
}

fn high(page: u16) -> Option<&'static [char; 128]> {
    tables::PAGES
        .iter()
        .find(|(p, _)| *p == page)
        .map(|(_, high)| high)
}

/// Whether `page` is one [`decode`] and [`encode`] know.
pub fn known(page: u16) -> bool {
    high(page).is_some()
}

/// `bytes` read as code page `page`; `None` for a page not here.
pub fn decode(bytes: &[u8], page: u16) -> Option<String> {
    let high = high(page)?;
    Some(
        bytes
            .iter()
            .map(|&b| match b {
                0x80.. => high[(b - 0x80) as usize],
                _ => b as char,
            })
            .collect(),
    )
}

/// `text` written in code page `page`, a character it lacks as `?`;
/// `None` for a page not here.
pub fn encode(text: &str, page: u16) -> Option<Vec<u8>> {
    let high = high(page)?;
    Some(
        text.chars()
            .map(|c| match c {
                '\0'..='\x7F' => c as u8,
                '\u{FFFD}' => b'?',
                _ => high
                    .iter()
                    .position(|&h| h == c)
                    .map_or(b'?', |i| 0x80 + i as u8),
            })
            .collect(),
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Known bytes of every page, as Windows reads them.
    #[test]
    fn codepage_tables_decode_known_bytes() {
        let cases: &[(u16, u8, char)] = &[
            (437, 0x80, 'Ç'),
            (437, 0xB0, '░'),
            (437, 0xE1, 'ß'),
            (850, 0x9B, 'ø'),
            (850, 0xD5, 'ı'),
            (852, 0xA5, 'ą'),
            (866, 0x80, 'А'),
            (866, 0xEF, 'я'),
            (874, 0xA1, 'ก'),
            (1250, 0x8A, 'Š'),
            (1250, 0xF5, 'ő'),
            (1251, 0xC0, 'А'),
            (1251, 0xFF, 'я'),
            (1253, 0xC1, 'Α'),
            (1254, 0xF0, 'ğ'),
            (1255, 0xE0, 'א'),
            (1256, 0xC7, 'ا'),
            (1257, 0xE0, 'ą'),
            (1258, 0xD0, 'Đ'),
            (10000, 0x80, 'Ä'),
            (10000, 0xA5, '•'),
            (10000, 0xDB, '€'),
            (10000, 0xBD, '\u{2126}'),
            (28591, 0xA4, '¤'),
            (28591, 0x80, '\u{80}'),
            (28605, 0xA4, '€'),
            (28605, 0xBD, 'œ'),
        ];
        for &(page, byte, want) in cases {
            assert_eq!(
                decode(&[b'a', byte], page),
                Some(format!("a{want}")),
                "{page} {byte:#04x}"
            );
        }
        assert_eq!(decode(b"x", 1252), None, "1252 is textio's own table");
        assert_eq!(decode(b"x", 932), None);
    }

    /// A byte Windows reads as a private-use character is undefined here.
    #[test]
    fn private_use_bytes_read_as_replacement() {
        assert_eq!(decode(&[0xAA], 1253).unwrap(), "\u{FFFD}");
        assert_eq!(decode(&[0xDB], 874).unwrap(), "\u{FFFD}");
        for (page, high) in tables::PAGES {
            assert!(
                !high.iter().any(|c| ('\u{E000}'..='\u{F8FF}').contains(c)),
                "{page}"
            );
        }
    }

    /// No two bytes of a page read as one character (so a write is well
    /// defined), and every character a page reads writes back as its byte.
    #[test]
    fn codepage_round_trips() {
        for (page, high) in tables::PAGES {
            for (i, &c) in high.iter().enumerate() {
                if c == '\u{FFFD}' {
                    continue;
                }
                assert_eq!(
                    high.iter().position(|&h| h == c),
                    Some(i),
                    "{page}: {c:?} at two bytes"
                );
                assert!((c as u32) >= 0x80, "{page}: high byte reads as ASCII");
            }
            let bytes: Vec<u8> = (0u8..=0xFF)
                .filter(|&b| b < 0x80 || high[(b - 0x80) as usize] != '\u{FFFD}')
                .collect();
            let text = decode(&bytes, *page).unwrap();
            assert_eq!(encode(&text, *page).unwrap(), bytes, "{page}");
        }
    }

    #[test]
    fn a_character_the_page_lacks_is_written_as_a_question_mark() {
        assert_eq!(encode("aÄ中€", 437).unwrap(), b"a\x8E??");
        assert_eq!(encode("é", 866).unwrap(), b"?");
        assert_eq!(encode("x", 932), None);
    }
}
